INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Professional Digital Soldering Station', 'professional-digital-soldering-station', 'Tools', 'Weller', 'WD-80', 189.99, 15, 4.8, 142, 25, '/products/prod_1_soldering_1783336796232.png', '["/products/prod_1_soldering_1783336796232.png"]', 'High-precision digital soldering station with temperature control, rapid heating, and an ergonomic heat-resistant handle.', '{"overview":"The Weller Digital Soldering Station is designed for professional technicians and hobbyists alike. It offers precise temperature regulation, dynamic heat recovery, and a digital LCD panel to display real-time telemetry. Its compact size ensures it fits neatly on any workbench.","purpose":"Provide highly stable and controllable thermal energy for delicate surface-mount components (SMD) and through-hole soldering tasks.","features":["Digital LCD screen for precise temperature control and adjustment","Fast heating element reaching 350°C in less than 30 seconds","Automatic standby and sleep modes for energy efficiency and tip protection","Password lock feature to lock custom temperature settings","Heat-resistant silicon cable and ergonomic handpiece with soft grip"],"applications":["SMD and through-hole electronic component repair","PCB prototype assembly and modification","Wire splicing and cable connector terminations","Small metal crafts and jewelry repair"],"advantages":["Accurate temperature control prevents heat damage to sensitive components","Extremely quick heat-up reduces idle time on the workbench","Includes auto-cooling and timeout features to increase safety","Compatible with a wide range of official Weller soldering tips"]}', '{"Operating Voltage":"230V AC / 50Hz","Power Output":"80 Watts","Temperature Range":"100°C to 480°C (212°F to 896°F)","Temperature Accuracy":"± 2°C (± 4°F)","Heating Element":"Premium Ceramic Core","Dimensions":"150 x 125 x 90 mm","Weight":"1.89 kg","ESD Safe":"Yes","Display Type":"Backlit LCD","Tip-to-Ground Resistance":"< 2 Ohms","Warranty":"2 Years Manufacturer Warranty","Country of Origin":"Germany"}', '[{"name":"Digital Soldering Station Console","count":1},{"name":"Ergonomic Soldering Iron Handpiece","count":1},{"name":"Safety Iron Stand with Brass Sponge Holder","count":1},{"name":"Premium Brass Sponge & Cleaning Sponge","count":1},{"name":"Pre-installed Fine Chisel Tip (1.6mm)","count":1},{"name":"Grounding Cable","count":1},{"name":"Detailed User Manual","count":1}]', 0, 0, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Precision Hot Air Rework Station', 'precision-hot-air-rework-station', 'Tools', 'Quick', 'Q-861DW', 249.99, 10, 4.7, 86, 12, '/products/prod_2_hotair_1783336806044.png', '["/products/prod_2_hotair_1783336806044.png"]', 'Professional closed-loop hot air station for desoldering QFP, SOP, PLCC, and BGA components safely.', '{"overview":"The Quick Precision Hot Air Rework Station uses an advanced brushless fan system to provide smooth, high-volume hot air flow. The closed-loop temperature control allows precise thermal adjustments, making it the perfect choice for professional surface mount component repair.","purpose":"Provide uniform, contact-free hot air stream to desolder and rework complex IC packages and small SMD parts.","features":["Brushless vortex motor for super silent and uniform airflow","Sensor closed loop temperature control with high power output","Automatic cooling function to protect heating element lifespan","Includes three specialized round nozzles (5mm, 6.4mm, 8mm)","Digital readout display for precise airflow and temperature monitoring"],"applications":["Desoldering BGA, QFP, SOP, PLCC and SOIC chips","Thermal shrink tubing applications","Plastic molding and warming test operations","Glue removal and adhesive softening"],"advantages":["No direct contact prevents scratching or moving adjacent tiny SMDs","Closed loop sensors maintain exact temperature regardless of air speed","Excellent build quality built for continuous industrial/lab usage"]}', '{"Operating Voltage":"110V/220V AC selectable","Power Output":"1000 Watts","Temperature Range":"100°C to 500°C","Airflow Capacity":"1 to 120 Liters/Minute","Noise Level":"< 45 dB","Dimensions":"188 x 245 x 135 mm","Weight":"3.65 kg","Display Type":"Large LED Digital Screen","Warranty":"1 Year Manufacturer Warranty","Country of Origin":"China"}', '[{"name":"Hot Air Station Unit","count":1},{"name":"Hot Air Handpiece with Holder","count":1},{"name":"Air Nozzles (5mm, 6.4mm, 8.5mm)","count":3},{"name":"Power Cord","count":1},{"name":"User Instruction Booklet","count":1}]', 0, 1, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Ergonomic Flush Wire Cutters', 'ergonomic-flush-wire-cutters', 'Tools', 'Knipex', 'KNX-78-03', 29.99, 0, 4.9, 312, 98, '/products/prod_3_cutters_1783336819821.png', '["/products/prod_3_cutters_1783336819821.png"]', 'Ultra-sharp precision flush cutters for clean, close cutting on copper and soft wires. Crafted with high-grade carbon steel.', '{"overview":"Knipex Super Knips are professional-grade electronic wire cutters. With precision-ground cutting edges without bevel, they ensure smooth flush cutting on components and circuit boards. High-comfort handles reduce hand fatigue during long assembly sessions.","purpose":"Cut delicate copper, component leads, and soft wire flush to the board surface without transmitting shock to the solder joints.","features":["Precision-ground blades with micro cutting-edge offset for extreme longevity","Extremely smooth movement with friction-free return spring","Constructed with hardened surgical steel with high corrosion resistance","Two-component multi-grip sleeves for maximum hand ergonomics","Includes wire lead catcher to prevent clippings from flying"],"applications":["Cutting components leads on through-hole printed circuit boards","Trimming copper wire up to 1.6mm diameter","Trimming plastic components and cable ties","Delicate model making and structural prototypes"],"advantages":["No bevel design yields a perfectly flat cut right at the PCB surface","Extremely long-lasting sharpness compared to standard hardware cutters","Handy wire catcher keeps workspace neat and safe"]}', '{"Material":"Special Tool Steel, Oil-hardened","Cutting Capacity (Soft Wire)":"Ø 0.2 - 1.6 mm","Cutting Capacity (Medium-Hard)":"Ø 1.2 mm","Length":"125 mm","Weight":"56 grams","Handle Finish":"Multi-component Grips","ESD Protection":"Yes (Conforms to DIN EN 61340-5-1)","Warranty":"Lifetime Limited Warranty","Country of Origin":"Germany"}', '[{"name":"Super Knips Flush Cutter (125mm)","count":1},{"name":"Blade Guard Plastic Cover","count":1},{"name":"Lead Catcher Attachment","count":1}]', 0, 2, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Auto-Ranging Digital Multimeter', 'auto-ranging-digital-multimeter', 'Tools', 'Fluke', 'FLK-115', 179.99, 5, 4.8, 215, 45, '/products/prod_4_multimeter_1783336842806.png', '["/products/prod_4_multimeter_1783336842806.png"]', 'Compact True-RMS multimeter for field service technicians, featuring auto-ranging, voltage detection, and backlit display.', '{"overview":"The Fluke 115 Digital Multimeter is the go-to testing companion for electrical and electronic troubleshooters. Featuring an intuitive interface, True-RMS AC measurements, and high safety certification, it delivers reliable readings every single time.","purpose":"Perform troubleshooting, testing, and measurements on AC/DC voltage, resistance, current, continuity, and capacitance.","features":["True-RMS measurements for accurate readings on non-linear loads","Large, highly visible white LED backlit display for dark areas","Low input impedance (LoZ) to prevent false ghost readings","Resistance, continuity, frequency, and capacitance measurements","CAT III 600 V safety rated for commercial and industrial use"],"applications":["Circuit troubleshooting and power supply verification","Checking capacitor and resistor tolerances","Continuity testing in cables, wires, and circuit traces","Automotive electrical testing and appliance repairs"],"advantages":["Rugged external holster shields against impacts and 2m drops","Auto-ranging feature automatically selects the best measurement resolution","True-RMS makes it accurate on modern complex wave forms"]}', '{"DC Voltage Range":"600.0 mV to 600.0 V","AC Voltage Range":"600.0 mV to 600.0 V (True-RMS)","DC Amps Range":"6.000 A to 10.00 A","Resistance Range":"600.0 Ohms to 40.00 M-Ohms","Capacitance Range":"1000 nF to 9999 µF","Frequency Range":"99.99 Hz to 50.00 kHz","Safety Rating":"CAT III 600 V","Battery Type":"9V Alkaline (400 hours typical)","Dimensions":"167 x 84 x 46 mm","Weight":"550 grams (including battery)","Warranty":"3 Years Limited Warranty","Country of Origin":"USA"}', '[{"name":"Fluke 115 Multimeter Console","count":1},{"name":"Yellow Protective Rubber Holster","count":1},{"name":"TL75 Hard Point Test Lead Set","count":1},{"name":"Pre-installed 9V Battery","count":1},{"name":"Certificate of Calibration","count":1},{"name":"Quick Start Guide","count":1}]', 0, 3, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Mixed Domain Digital Oscilloscope', 'mixed-domain-digital-oscilloscope', 'Tools', 'Rigol', 'DS1104Z', 399.99, 8, 4.8, 67, 8, '/products/prod_5_oscilloscope_1783336873444.png', '["/products/prod_5_oscilloscope_1783336873444.png"]', '4-Channel 100MHz digital oscilloscope with large screen, built-in waveform generator, and serial decoding capabilities.', '{"overview":"The Rigol DS1104Z Plus is an extremely popular 4-channel digital oscilloscope. Boasting a 100MHz bandwidth and a deep memory depth, it provides detailed visualization of high-speed signals. Perfect for debugging microcontrollers, SPI/I2C buses, and analog circuits.","purpose":"Graphically display electrical voltage waveforms over time to analyze signal behavior, integrity, and noise.","features":["4 analog channels with 100 MHz bandwidth","1 GSa/s real-time sample rate on single channel","Innovative UltraVision technology for intensity graded display","Deep memory depth up to 24 Mpts for zooming into detail","Free serial bus trigger and decode package (I2C, SPI, RS232, UART)"],"applications":["Debugging serial communication protocols","Measuring signal noise, rise/fall times and frequency jitter","Analyzing analog filters and amplifier circuits","Education labs and digital design prototyping"],"advantages":["4 channels allow viewing input, output, and multiple communication lines simultaneously","Large 7-inch TFT color display makes tracking multiple waveforms easy","Rich trigger menu including edge, pulse, slope, video, and pattern options"]}', '{"Bandwidth":"100 MHz","Analog Channels":"4 Channels","Real-time Sample Rate":"1.0 GSa/s (Max)","Max Memory Depth":"24 Mpts (Standard)","Waveform Capture Rate":"30,000 wfms/s","Vertical Sensitivity":"1 mV/div to 10 V/div","Vertical Resolution":"8 bits","Interface":"USB Host, USB Device, LAN (LXI)","Display":"7.0 inch WVGA (800x480) TFT Color LCD","Dimensions":"313 x 160.8 x 122.4 mm","Weight":"3.2 kg","Warranty":"3 Years Manufacturer Warranty","Country of Origin":"China"}', '[{"name":"Rigol DS1104Z Plus Oscilloscope Mainframe","count":1},{"name":"PVP2200 200MHz Passive Probes (1x/10x)","count":4},{"name":"USB Interface Cable","count":1},{"name":"Power Cord (Regional)","count":1},{"name":"Calibration Certificate","count":1},{"name":"Quick Reference User Guide","count":1}]', 0, 4, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Linear Triple Output DC Power Supply', 'linear-triple-output-dc-power-supply', 'Instruments', 'Rigol', 'DP832', 349.99, 12, 4.6, 45, 6, '/products/prod_6_power_supply_1783336885030.png', '["/products/prod_6_power_supply_1783336885030.png"]', 'Highly stable, low ripple linear DC power supply with three independent channels, total 195W power, and programmable USB control.', '{"overview":"The DP832 is a triple-channel, high-performance programmable linear DC power supply. Featuring low ripple and noise, rapid transient response, and excellent line/load regulation, it is an essential instrument for powering sensitive circuits.","purpose":"Deliver clean, regulated, adjustable DC voltage and current to electronic projects and devices during testing.","features":["3 isolated channels: 30V/3A, 30V/3A, and 5V/3A","Extremely low ripple and noise: < 350 µVrms / 2 mVpp","Fast transient response time: < 50 µs","Built-in overvoltage (OVP) and overcurrent (OCP) safety limits","USB, LAN, and digital IO interfaces for full remote control"],"applications":["Powering op-amps, microcontrollers, and logic circuits","Product stress testing and voltage sweeps","Simulating fluctuating battery conditions","General-purpose electronics bench testing"],"advantages":["Linear topology ensures virtually zero high-frequency switching noise","Independent isolation allows channels to be connected in series or parallel","Bright 3.5 inch color display shows real-time V/A/W graphs"]}', '{"Total Power":"195 Watts","Output Channels":"3 (CH1: 0-30V/3A, CH2: 0-30V/3A, CH3: 0-5V/3A)","Load Regulation":"Voltage: < 0.01% + 2mV, Current: < 0.01% + 250µA","Line Regulation":"Voltage: < 0.01% + 2mV, Current: < 0.01% + 250µA","Ripple and Noise":"< 350 µVrms / 2 mVpp (20Hz to 20MHz)","Response Time":"< 50 µs (50% to 100% load change)","Display Screen":"3.5\\" TFT Color LCD","Dimensions":"239 x 157 x 418 mm","Weight":"10.5 kg","Warranty":"3 Years Manufacturer Warranty","Country of Origin":"China"}', '[{"name":"Rigol DP832 DC Power Supply Console","count":1},{"name":"Heavy Duty Crocodile Clip Lead Set","count":3},{"name":"USB Communications Cable","count":1},{"name":"Fuse Spares (5A)","count":2},{"name":"AC Power Lead","count":1},{"name":"Product Safety Instructions Booklet","count":1}]', 0, 5, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Dual-Channel Arbitrary Function Generator', 'dual-channel-arbitrary-function-generator', 'Instruments', 'Siglent', 'SDG1032X', 289.99, 10, 4.5, 32, 9, '/products/prod_7_func_gen_1783336896544.png', '["/products/prod_7_func_gen_1783336896544.png"]', '30MHz DDS signal generator with dual output channels, 150MSa/s sample rate, and built-in standard and arbitrary waveforms.', '{"overview":"The Siglent SDG1032X is a dual-channel function/arbitrary waveform generator. Using innovative EasyPulse technology, it produces stable, low-jitter square waves and pulses up to 30MHz. Perfect for simulating sensor inputs, clock signals, and testing filters.","purpose":"Generate predictable, repeatable periodic electrical waveforms (sine, square, triangle, noise, etc.) to inject into a test circuit.","features":["Dual independent channels with copy/tracking settings","Maximum output frequency of 30 MHz","150 MSa/s sampling rate with 14-bit vertical resolution","EasyPulse technology preserves fast rise/fall edges even at low frequency","Includes sweep, burst, and multiple modulation types (AM, FM, PM, PWM)"],"applications":["Simulating complex sensor signals for microcontrollers","Testing frequency response of amplifiers and passive filters","Generating clock references for digital communication circuits","Acoustic and vibration testing"],"advantages":["Dual channels allow running two phase-aligned signals simultaneously","Arbitrary shape editing software included to draw custom waves","High frequency stability and low distortion output"]}', '{"Max Frequency":"30 MHz","Output Channels":"2 Channels","Sampling Rate":"150 MSa/s","Vertical Resolution":"14 bits","Waveform Length":"16 kpts","Standard Waveforms":"Sine, Square, Ramp, Pulse, Noise, DC, Arb","Modulation Types":"AM, FM, PM, ASK, FSK, PSK, PWM, Sweep, Burst","Display":"3.5 inch TFT Color Display","Dimensions":"296 x 107 x 124 mm","Weight":"3.4 kg","Warranty":"3 Years Manufacturer Warranty","Country of Origin":"China"}', '[{"name":"SDG1032X Waveform Generator Console","count":1},{"name":"BNC-to-BNC Cable (1m)","count":1},{"name":"BNC-to-Crocodile Clip Lead","count":1},{"name":"USB Cable","count":1},{"name":"AC Power Cord","count":1},{"name":"Quick Start Guide & CD Software","count":1}]', 0, 6, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('High-Speed 16-Channel Logic Analyzer', 'high-speed-16-channel-logic-analyzer', 'Instruments', 'Saleae', 'Logic-Pro-16', 499.99, 0, 4.9, 18, 5, '/products/prod_8_logic_analyzer_1783336907806.png', '["/products/prod_8_logic_analyzer_1783336907806.png"]', 'Premium USB-based 16-channel logic analyzer and mixed-signal recorder. Captures digital and analog signals with state-of-the-art software.', '{"overview":"The Saleae Logic Pro 16 is a USB-based digital diagnostic tool. Designed for embedded systems developers, it records digital lines and analog signals side-by-side. The cross-platform Saleae Logic software automatically decodes SPI, I2C, CAN, USB, and 20+ other communication protocols.","purpose":"Capture and debug high-speed digital state transactions and analog voltage levels on microchip interfaces.","features":["16 digital channels plus 16 analog channels (shared inputs)","Captures digital signals up to 500 MSa/s","Captures analog signals up to 50 MSa/s with 12-bit ADC","USB 3.0 SuperSpeed connection for streaming unlimited data to PC","Aluminum enclosure for excellent shielding and durability"],"applications":["Debugging firmware and communication registers","Analyzing microsecond timing errors on SPI/I2C/CAN buses","Monitoring analog voltages of ADC/DAC circuits","Reverse engineering communication protocols"],"advantages":["Extremely intuitive software makes searching millions of samples instant","Compact pocket-sized design powered fully by USB","Supports Windows, macOS, and Linux out of the box"]}', '{"Digital Channels":"16 Channels","Analog Channels":"16 Channels (Shared with digital)","Max Digital Sample Rate":"500 MSa/s","Max Analog Sample Rate":"50 MSa/s","Analog Bandwidth":"5 MHz","Voltage Range":"-10.00 V to +10.00 V","PC Connection":"USB 3.0","Enclosure Material":"Anodized Aluminum","Supported OS":"Windows 10/11, macOS 10.14+, Linux Ubuntu","Warranty":"2 Years Manufacturer Warranty","Country of Origin":"USA"}', '[{"name":"Saleae Logic Pro 16 Unit","count":1},{"name":"Test Lead Wire Harnesses (9-pin)","count":2},{"name":"Micro Grabber Test Clips","count":18},{"name":"USB 3.0 Connection Cable (1.5m)","count":1},{"name":"Premium Neoprene Carrying Case","count":1}]', 0, 7, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('True-RMS AC/DC Clamp Meter', 'true-rms-ac-dc-clamp-meter', 'Instruments', 'Fluke', 'FLK-325', 219.99, 0, 4.7, 58, 19, '/products/prod_9_clamp_meter_1783336917964.png', '["/products/prod_9_clamp_meter_1783336917964.png"]', 'Rugged AC/DC clamp meter for commercial and residential electricians. Measures current up to 400A without breaking the circuit.', '{"overview":"The Fluke 325 is a True-RMS clamp meter designed for commercial and residential electricians. Featuring a slim jaw profile, it allows easy access in crowded cable panels and measures AC/DC current, voltage, frequency, and temperature.","purpose":"Safely measure high electrical currents in active conductors without physically breaking or cutting the wire loop.","features":["AC/DC current measurement up to 400 A","AC/DC voltage measurement up to 600 V","True-RMS sensing for accurate readings on distorted waveforms","Resistance measurement up to 40 k-Ohms with continuity test","Large backlight display and Min/Max recording values"],"applications":["Measuring motor load currents in HVAC systems","Verifying distribution panel load balance","Measuring charging currents on solar and battery banks","Residential electrical troubleshooting"],"advantages":["Jaw opening accommodates cables up to 30mm diameter","Includes Type-K thermocouple for quick temperature checks","Slim, compact body fits comfortably in pocket or tool pouch"]}', '{"AC Current Range":"40.00 A / 400.0 A","DC Current Range":"40.00 A / 400.0 A","AC Voltage Range":"600.0 V (True-RMS)","DC Voltage Range":"600.0 V","Resistance":"400.0 Ohms to 40.00 k-Ohms","Frequency Range":"5.0 Hz to 500.0 Hz","Temperature Range":"-10.0°C to 400.0°C (with probe)","Max Wire Diameter":"30 mm","Safety Rating":"CAT III 600V / CAT IV 300V","Warranty":"2 Years Manufacturer Warranty","Country of Origin":"USA"}', '[{"name":"Fluke 325 Clamp Meter Console","count":1},{"name":"TL75 Hard Point Test Leads","count":1},{"name":"80BK-A Type-K Thermocouple Probe","count":1},{"name":"Soft Zipper Carrying Pouch","count":1},{"name":"AAA Batteries (Pre-installed)","count":2},{"name":"User manual","count":1}]', 0, 8, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Autonomous Arduino Robotics Starter Kit', 'autonomous-arduino-robotics-starter-kit', 'Projects', 'Arduino', 'ARD-2WD-KIT', 89.99, 20, 4.7, 184, 50, '/products/prod_10_robot_kit_1783336926773.png', '["/products/prod_10_robot_kit_1783336926773.png"]', 'Complete educational DIY robotics kit based on Arduino Uno. Build an obstacle-avoiding, Bluetooth-controlled 2WD vehicle.', '{"overview":"Unleash your inner robotics engineer with this comprehensive Arduino Robotics Starter Kit. It contains all the parts, sensors, and structural chassis components to build your own intelligent mobile robot. Step-by-step interactive lessons guide you through assembly and coding.","purpose":"Learn core concepts of firmware programming, sensor integration, motor speed control, and autonomous decision-making algorithms.","features":["Includes Arduino Uno R3 compatible microcontroller board","Laser-cut durable acrylic dual-deck chassis","Ultrasonic distance sensor with micro servo mount for panning","L298N Dual H-bridge motor driver module","Bluetooth transceiver for smartphone application control"],"applications":["STEM and high school educational projects","Learning C++ Arduino programming language","Hobby robotics experimentation","Algorithmic maze solving and obstacle routing"],"advantages":["No soldering required – uses clean plug-and-play breadboard wiring","Fully open-source code templates provided","Expandable chassis with mounting holes for custom add-on sensors"]}', '{"Microcontroller":"ATmega328P (Arduino Uno)","Operating Voltage":"7V to 12V DC (via battery holder)","Motor Voltage":"3V - 9V DC Geared Motors","Chassis Material":"Acrylic (3mm thickness)","Communication":"Bluetooth HC-05 Module","Sensors Included":"Ultrasonic, Infrared Obstacle, Photoresistor","Programming Interface":"USB (Arduino IDE compatible)","Difficulty Level":"Beginner to Intermediate","Assembly Time":"2 to 3 Hours (Typical)","Warranty":"6 Months Limited Warranty","Country of Origin":"Italy"}', '[{"name":"Arduino Uno R3 Compatible Board","count":1},{"name":"Acrylic Chassis Plates & Hardware","count":2},{"name":"DC Geared Motors & Rubber Wheels","count":2},{"name":"L298N Motor Driver Shield","count":1},{"name":"Ultrasonic Distance Sensor HC-SR04","count":1},{"name":"SG90 Micro Servo Motor","count":1},{"name":"40-pin Jumper Wire Set (Male-Male/Male-Female)","count":2},{"name":"4x AA Battery Holder","count":1},{"name":"Assembly Screwdriver & Spanner","count":1}]', 0, 9, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Zigbee Smart Home IoT Learning Kit', 'zigbee-smart-home-iot-learning-kit', 'Projects', 'SparkFun', 'SF-IOT-32', 124.99, 10, 4.6, 56, 32, '/products/prod_11_iot_kit_1783336935122.png', '["/products/prod_11_iot_kit_1783336935122.png"]', 'Explore IoT (Internet of Things) with this ESP32 & Zigbee sensor development kit. Create custom smart home monitors and alerts.', '{"overview":"The Smart Home IoT Learning Kit lets you build and program real-world smart home systems. Featuring an ESP32 microchip with dual-core processor and wireless capabilities, it communicates with DHT22 temperature sensors, flame detectors, gas sensors, and relays. Hook it up to open-source Home Assistant or write custom MQTT servers.","purpose":"Learn to fetch real-world sensor data, transmit it wirelessly, and control appliances using relays and mobile apps.","features":["ESP32-WROOM development board with built-in Wi-Fi & BLE","Sensors for Temperature, Humidity, Soil Moisture, and Gas Leakage","5V electromagnetic relay module to trigger high-voltage appliances safely","Detailed tutorials for configuring MQTT, Home Assistant, and ESPHome","1602 LCD character display with I2C interface"],"applications":["Home automated greenhouse climate monitors","Fire and gas leak detection warning systems","Smart lighting triggers and automatic curtain timers","College IoT research projects"],"advantages":["Wi-Fi and Bluetooth allow direct smartphone connections without hubs","Sensors use I2C/SPI pins keeping breadboard routing neat","Comes with pre-configured dashboard webserver templates"]}', '{"Core Microchip":"ESP32-D0WDQ6 Dual-Core 240MHz","Wireless Protocol":"Wi-Fi 802.11 b/g/n, Bluetooth v4.2 BR/EDR & BLE","Input Voltage":"5V USB or 3.7V LiPo Battery","Display Module":"16x2 Character LCD (I2C interface, blue backlight)","Relay Rating":"10A @ 250V AC / 10A @ 30V DC","Programming support":"Arduino IDE, ESP-IDF, MicroPython, ESPHome","Sensors Included":"DHT22 (Temp/Hum), MQ-2 (Gas/Smoke), Soil Moisture, LDR","Warranty":"1 Year Manufacturer Warranty","Country of Origin":"USA"}', '[{"name":"ESP32 Dev Board pre-soldered","count":1},{"name":"DHT22 Precision Climate Sensor","count":1},{"name":"MQ-2 Flammable Gas Sensor","count":1},{"name":"Analog Soil Moisture probe","count":1},{"name":"5V Isolated Relay Module","count":1},{"name":"830 Tie-Point Breadboard","count":1},{"name":"40-pin Dupont Male-to-Male jumper bundle","count":1},{"name":"Micro USB Cable","count":1}]', 0, 10, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('Smart Line-Following Robot Kit', 'smart-line-following-robot-kit', 'Projects', 'Adafruit', 'ADA-RP2040-LF', 74.99, 15, 4.8, 74, 22, '/products/prod_12_line_bot_1783336946432.png', '["/products/prod_12_line_bot_1783336946432.png"]', 'An infrared sensor-based line tracker robot kit. Learn PID controller logic and calibration procedures.', '{"overview":"The Adafruit Line-Following Robot Kit is designed to teach PID (Proportional-Integral-Derivative) control systems. Featuring a multi-channel infrared sensor array and high-efficiency micro-metal gearmotors, it tracks complex tracks, intersecting curves, and sharp angles with high agility.","purpose":"Calibrate infrared sensors and implement a control loop to guide a robot vehicle along a dark track on a light surface.","features":["5-Channel high-sensitivity IR sensor array for high-accuracy tracking","TB6612FNG Dual DC Motor Driver for smooth speed control","Compact circular chassis ideal for spinning on its center point","Pre-written calibration script with autotuning options","High-performance micro-metal gearmotors with metal shafts"],"applications":["STEM school robotic competitions","Learning feedback loops and control theory","Micro-mouse maze routing experiments","PID parameter optimization studies"],"advantages":["Metal gearmotors offer significantly better torque and reliability than plastic equivalents","Onboard power switch saves battery when downloading firmware","Lightweight construction enables high-speed track navigation"]}', '{"Controller Board":"Adafruit Feather RP2040","Motor Driver":"TB6612FNG (Up to 1.2A continuous per channel)","Sensors":"5x Reflective IR Phototransistor Array","Motors":"2x Micro-Metal Gearmotors (150:1 gear ratio)","Maximum Speed":"0.8 Meters/Second","Power Source":"4x AAA Battery or 3.7V LiPo Battery","Dimensions":"115 x 115 x 65 mm","Weight":"190 grams (without batteries)","Warranty":"90 Days Limited Warranty","Country of Origin":"USA"}', '[{"name":"Feather RP2040 Microcontroller","count":1},{"name":"Feather Motor Wing Shield","count":1},{"name":"Anodized Aluminum Robot Chassis","count":1},{"name":"5-Channel IR Line-Tracking Sensor Board","count":1},{"name":"Micro-Metal Gearmotors & Rubber Tires","count":2},{"name":"Front Nylon Castor Ball Wheel","count":1},{"name":"LiPo Battery (3.7V, 500mAh)","count":1},{"name":"Instruction sheet and track paper","count":1}]', 0, 11, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('ESP32 Weather Station & IoT Kit', 'esp32-weather-station-and-iot-kit', 'Projects', 'SparkFun', 'SF-WEATH-32', 94.99, 5, 4.7, 42, 15, '/products/prod_13_weather_kit_1783336954845.png', '["/products/prod_13_weather_kit_1783336954845.png"]', 'Build an internet-connected weather monitoring station with Barometric Pressure, Temp, Humidity, and OLED display.', '{"overview":"The SparkFun Weather Station & IoT Kit is a full sensor dashboard kit. It is centered around a powerful ESP32 board and features the BME280 environmental sensor. Capture atmospheric pressure, altitude, humidity, and temperature. Send data automatically to cloud services like ThingSpeak or Adafruit IO, and display local data on a bright 0.96 inch OLED.","purpose":"Acquire high-precision weather parameters and publish them to cloud IoT databases.","features":["ESP32 IoT board with integrated LiPo charging circuit","High-accuracy BME280 sensor (Temp, Humidity, Pressure, Altitude)","0.96\\" 128x64 pixels Blue OLED display (I2C)","Pre-written code for cloud posting and energy-saving deep sleep","SparkFun Qwiic connectors for solderless daisy-chain hookup"],"applications":["Home microclimate and ambient weather loggers","Greenhouse environmental monitoring","IoT cloud telemetry and charting research","Low-power solar weather nodes"],"advantages":["Uses Qwiic connect system for absolute plug-and-play assembly","Deep sleep programming code drops power consumption to under 15 µA","Ready-made ThingSpeak dashboards with open API access templates"]}', '{"Board Processor":"ESP32 (WROOM-32E module)","Sensor Model":"Bosch BME280 (I2C/SPI)","Temp Range / Accuracy":"-40°C to 85°C / ± 1°C","Humidity Range / Accuracy":"0% to 100% RH / ± 3%","Pressure Range / Accuracy":"300 hPa to 1100 hPa / ± 1 hPa","Display Module":"0.96\\" I2C OLED SSD1306","Hookup System":"Qwiic Connector Cables (Included)","Operating Voltage":"3.3V DC (USB or LiPo)","Warranty":"1 Year Manufacturer Warranty","Country of Origin":"USA"}', '[{"name":"SparkFun ESP32 Thing Plus Board","count":1},{"name":"SparkFun BME280 Environmental Sensor breakout","count":1},{"name":"0.96\\" I2C OLED Display Module","count":1},{"name":"Qwiic Connect Cables (50mm)","count":2},{"name":"Breadboard & Rubber Feet","count":1},{"name":"Jumper Cable Pack","count":1},{"name":"Micro USB Cable (1m)","count":1}]', 0, 12, 1);
INSERT INTO products (name, slug, category, brand, model, price, discount, rating, reviews, stock, thumbnail, images, description, introduction, specifications, shipping_list, featured, sort_order, is_active) VALUES ('DIY FM Radio Soldering PCB Kit', 'diy-fm-radio-soldering-pcb-kit', 'Projects', 'Adafruit', 'ADA-FM-RDA', 19.99, 0, 4.8, 152, 120, '/products/prod_14_radio_kit_1783336964305.png', '["/products/prod_14_radio_kit_1783336964305.png"]', 'Start your soldering journey! Assemble a portable, functional FM radio tuner with digital search and speaker output.', '{"overview":"The DIY FM Radio Soldering PCB Kit is the ultimate project for learning how to solder. The circuit features an RDA5807 FM radio receiver chip, a power amplifier, and tact buttons for scan/volume control. All components are through-hole, making soldering straightforward.","purpose":"Practice through-hole soldering techniques and build a working analog/digital radio.","features":["High quality silkscreened PCB with clear component mapping outlines","RDA5807 FM radio receiver chip with auto search scan","Built-in LM386 low voltage audio power amplifier","Includes miniature 8-ohm 0.5W speaker","Powered by standard 2x AA batteries"],"applications":["Soldering training and introduction courses","DIY electronic hobby crafts","Learning basic audio amplifier stages","Hands-on electronics assembly kits"],"advantages":["Extremely detailed soldering manual with photographic steps","Wide pads and tracing lines prevents accidental solder bridges","Gives you a fully operational radio to listen to after completion"]}', '{"Radio Chipset":"RDA5807 (FM tuner)","FM Frequency Range":"76 MHz to 108 MHz","Amplifier Chip":"LM386 Audio Amp","Speaker Specification":"8 Ohms, 0.5W (Diameter 40mm)","Input Power":"3V DC (2x AA Batteries)","Current Draw":"About 40 mA","PCB dimensions":"82 x 65 mm","PCB Material":"FR-4 Fiber Glass","Difficulty Level":"Absolute Beginner","Warranty":"30 Days Return Warranty","Country of Origin":"USA"}', '[{"name":"Unassembled FM Radio FR-4 PCB","count":1},{"name":"Pre-programmed RDA5807 IC DIP-8","count":1},{"name":"LM386 Audio Amplifier IC DIP-8","count":1},{"name":"Resistors, Capacitors & Inductor Pack","count":1},{"name":"Tactile Press Buttons","count":5},{"name":"Telescopic Radio Antenna","count":1},{"name":"8 Ohm Speaker & Battery Case","count":1},{"name":"Detailed Assembly Instructions Booklet","count":1}]', 0, 13, 1);
