INSERT INTO settings (setting_key, setting_value, setting_type, order_position) VALUES ('blog_hero_title', 'Tech Articles &', 'text', 201), ('blog_hero_title_accent', 'Electronics Guides', 'text', 202), ('blog_hero_description', 'Expert-written guides on microcontrollers, firmware development, robotics, IoT, and custom PCB routing design.', 'text', 203), ('blog_search_placeholder', 'Search articles...', 'text', 204);
